/* @socom-skeleton stub _OnMissionComplete__Fv */
void _OnMissionComplete()
{
	/* 0x1f6dd0 (the mission's end, before the exit state): silence every sound, close the
	 * sound banks and the jukebox, stop the player's rumble and the "common" and "mission"
	 * anim sets, flush the input; a network game also clears the player's projectiles and
	 * closes the pickups. Then every entity's OnMissionEnd, the camera zoom back to 1 and
	 * the third-person view (m_ctrl_view 0). */
	CSndInstance::StopAllSounds();
	CSnd::Close();
	CSndJukebox::Stop();

	CZSealBody *player = ftsGetPlayer();
	CSealCtrl *control = player != NULL ? static_cast<CSealCtrl *>(player->m_control) : NULL;

	if (control != NULL)
		control->StopRumbler();

	CZAnimSet *set = ZAnim.GetAnimSet("common");

	if (set != NULL)
		set->Stop();

	set = ZAnim.GetAnimSet("mission");

	if (set != NULL)
		set->Stop();

	CInput::Flush();

	if (theNetwork.m_bNetwork)
	{
		CZProjectileList *projectiles = CZWeapon::m_pProjectilelist;
		player = ftsGetPlayer();
		projectiles->Clear(player != NULL ? player->m_id : 0);
		CPickup::Close(false);
	}

	for (CEntityList::iterator it = CEntity::m_list.begin(); it != CEntity::m_list.end(); ++it)
		(*it)->OnMissionEnd();

	appCamera->SetZoom(1.0f);
	appCamera->m_ctrl_view = static_cast<CAMVIEW>(0);
}

/* @socom-skeleton body Tick__8CMissionFf */
void CMission::Tick(f32 dT)
{
	/* 0x1f6b40 (via the Mission task): the mission clocks, the objectives (single player)
	   or the network game, then the end valves - complete, failure, abort, timeout, in
	   that order, a set valve ends the mission (only abort when objectives are ignored) -
	   the spawners and the firefight state. Was a guess that ended the mission whenever
	   a valve was clear. */
	m_timer += dT;

	if (!(m_wait_before_falling <= 0.0f))
		m_wait_before_falling -= dT;

	m_winlosstimer += m_winlossinc * dT;

	if (theNetwork.m_bNetwork && m_pNetGame != NULL)
	{
		/* port: not written - the network game (0x1f6bb8-0x1f6cd4: CNetClock::Tick, the
		   game timer valve, CZGameState::UpdateLocalGame, the client's game-over push of
		   theGame+0x1d8); the port has no network play */
	}
	else
	{
		TickObjectives(dT);
	}

	if (!m_ignore_objectives)
	{
		if (m_valve_complete->m_value)
			OnMissionComplete(MISSION_SUCCESS);
		else if (m_valve_failure->m_value)
			OnMissionComplete(MISSION_FAILURE);
		else if (m_valve_abort->m_value)
			OnMissionComplete(MISSION_ABORTED);
		else if (m_valve_timeout->m_value)
			OnMissionComplete(MISSION_TIMEOUT);
	}
	else if (m_valve_abort->m_value)
	{
		OnMissionComplete(MISSION_ABORTED);
	}

	spawners.Tick(dT);
	TickInFirefight(dT);
}

/* @socom-skeleton stub TickObjectives__8CMissionFf */
void CMission::TickObjectives(float dT)
{
	/* 0x1f6610, once a second (the objective list passes 1000 to force it): the compass
	 * anchor of the objective picked on the map, else of the first open objective, and
	 * anchors of completed objectives deleted */
	m_objectives_timer += dT;

	if (m_objectives_timer <= 1.0f)
		return;

	m_objectives_timer = 0.0f;
	CMissionObjectiveCam* selected = theHUD->m_newmap.m_objectivelist.GetCurrentObjectiveRetainer();

	if (selected != NULL && selected->IsAvailable() && m_prev_selected_objcam != selected)
	{
		for (u32 i = 0; i < m_objanchor_vec.size(); i++)
			CZSealBody::m_compass.DeleteAnchor(m_objanchor_vec[i].m_anchor); /* port: DeleteAnchor is declared a member; the ELF one is static */

		m_objanchor_vec.clear();

		CPnt3D pos;
		pos.x = selected->m_pos.x;
		pos.y = 0.0f;
		pos.z = selected->m_pos.y;

		SObjectiveCam_Anchor entry = { NULL, NULL };
		m_objanchor_vec.push_back(entry);
		SObjectiveCam_Anchor& added = m_objanchor_vec.back();
		added.m_objective = selected;

		if (selected->m_isSecondary)
		{
			added.m_anchor = CCompass::CreateAnchor(pos, "SECONDARY OBJ");
			added.m_anchor->m_type = 7;
		}
		else
		{
			added.m_anchor = CCompass::CreateAnchor(pos, "PRIMARY OBJ");
			added.m_anchor->m_type = 6;
		}

		m_prev_selected_objcam = added.m_objective;
		return;
	}

	if (m_objanchor_vec.size() == 0)
	{
		/* the first open objective; when it is closed but the next one is a secondary,
		 * the first open secondary after it */
		bool found = false;

		for (std::list<void const*>::iterator it = m_objectivecams.begin(); it != m_objectivecams.end() && !found; ++it)
		{
			std::list<void const*>::iterator next = it;
			++next;
			CMissionObjectiveCam* cam = (CMissionObjectiveCam*)*it;
			bool skip = true;

			if (next != m_objectivecams.end() && ((CMissionObjectiveCam*)*next)->m_isSecondary && !cam->IsAvailable())
				skip = false;

			if (cam->IsAvailable())
			{
				CPnt3D pos;
				pos.x = cam->m_pos.x;
				pos.y = 0.0f;
				pos.z = cam->m_pos.y;

				SObjectiveCam_Anchor entry = { NULL, NULL };
				m_objanchor_vec.push_back(entry);
				SObjectiveCam_Anchor& added = m_objanchor_vec.back();
				added.m_objective = cam;
				/* ELF quirk kept: named and typed a primary even for a secondary objective */
				added.m_anchor = CCompass::CreateAnchor(pos, "PRIMARY OBJ");
				added.m_anchor->m_type = 6;
				found = true;
			}
			else if (!skip)
			{
				for (; next != m_objectivecams.end() && !found; ++next)
				{
					CMissionObjectiveCam* secondary = (CMissionObjectiveCam*)*next;

					if (!secondary->m_isSecondary || !secondary->IsAvailable())
						continue;

					CPnt3D pos;
					pos.x = secondary->m_pos.x;
					pos.y = 0.0f;
					pos.z = secondary->m_pos.y;

					SObjectiveCam_Anchor entry = { NULL, NULL };
					m_objanchor_vec.push_back(entry);
					SObjectiveCam_Anchor& added = m_objanchor_vec.back();
					added.m_objective = secondary;
					added.m_anchor = CCompass::CreateAnchor(pos, "SECONDARY OBJ");
					added.m_anchor->m_type = 7;
					found = true;
				}
			}
		}
	}

	u32 count = m_objanchor_vec.size();

	for (u32 i = 0; i < count; i++)
	{
		if (!m_objanchor_vec[i].m_objective->IsComplete())
			continue;

		CZSealBody::m_compass.DeleteAnchor(m_objanchor_vec[i].m_anchor);
		u32 last = m_objanchor_vec.size() - 1;

		if (m_objanchor_vec.size() >= 2 && i != last)
		{
			SObjectiveCam_Anchor swap = m_objanchor_vec[i];
			m_objanchor_vec[i] = m_objanchor_vec[last];
			m_objanchor_vec[last] = swap;
		}

		m_objanchor_vec.pop_back();
		count = m_objanchor_vec.size();
		i--;
	}
}

