/* @socom-skeleton stub LoadMissionCams__8CMissionFP8CRdrFile */
void CMission::LoadMissionCams(CRdrFile *reader)
{
	/* 0x1f31b0 (Open): missioncams.rdr MISSIONCAMS - each entry with a NAME becomes a
	 * mission camera (IDENTIFIER, NAME, DESCRIPTION, DESCRIPTION2, DESCRIPTION3,
	 * ON_CALL_ANIMATION, ON_CALL_MUSIC); the old ones are deleted first. ELF: returns 1
	 * (0 without the reader or the tag; no caller reads it) */
	for (std::list<CMissionCam*>::iterator it = m_missioncams.begin(); it != m_missioncams.end(); ++it)
		delete *it;

	m_missioncams.clear();

	if (reader == NULL)
		return;

	_zrdr* cams = zrdr_findtag(reader, "MISSIONCAMS");

	if (cams == NULL)
		return;

	for (u32 i = 0; i < (cams->IsArray() ? (u32)(cams->array->integer - 1) : 0u); i++)
	{
		_zrdr* cam = cams->Get(i);
		char* identifier = zrdr_findstring(cam, "IDENTIFIER");
		char* name = zrdr_findstring(cam, "NAME");
		char* description1 = zrdr_findstring(cam, "DESCRIPTION");
		char* description2 = zrdr_findstring(cam, "DESCRIPTION2");
		char* description3 = zrdr_findstring(cam, "DESCRIPTION3");
		char* animation = zrdr_findstring(cam, "ON_CALL_ANIMATION");
		char* music = zrdr_findstring(cam, "ON_CALL_MUSIC");

		if (name == NULL)
			continue;

		CMissionCam* mission_cam = new CMissionCam();
		mission_cam->Set(identifier, name, description1, description2, description3, animation, music);
		m_missioncams.insert(m_missioncams.end(), mission_cam);
#ifdef SOCOM_PORT
		SOCOM_PORT_TRACE("MISSIONCAM: %s (%s) anim %s -> %p", mission_cam->m_identifier,
			description1 != NULL ? description1 : "", animation != NULL ? animation : "-", mission_cam->m_anim);
#endif
	}
}

/* @socom-skeleton stub LoadObjectiveCams__8CMissionFP8CRdrFile */
void CMission::LoadObjectiveCams(CRdrFile *rdr)
{
	/* 0x1f2ca0 (bool in v0, the one caller ignores it): the objectives of hudobjectives.rdr
	 * HUD_OBJECTIVES, after the old ones are deleted. An entry without a NAME is skipped. */
	for (std::list<void const*>::iterator it = m_objectivecams.begin(); it != m_objectivecams.end(); ++it)
		delete (CMissionObjectiveCam*)*it;

	m_objectivecams.clear();

	if (rdr == NULL)
		return;

	_zrdr* list = zrdr_findtag(rdr, "HUD_OBJECTIVES");

	if (list == NULL)
		return;

	for (u32 i = 0; i < (list->IsArray() ? static_cast<u32>(list->array->integer - 1) : 0); i++)
	{
		_zrdr* entry = list->Get(i);
		char* identifier = zrdr_findstring(entry, "IDENTIFIER");
		char* name = zrdr_findstring(entry, "NAME");
		char* description = zrdr_findstring(entry, "DESCRIPTION");
		char* description2 = zrdr_findstring(entry, "DESCRIPTION2");
		char* description3 = zrdr_findstring(entry, "DESCRIPTION3");
		char* valve = zrdr_findstring(entry, "VALVE");
		char* invalid_valve = zrdr_findstring(entry, "INVALID_VALVE");
		char* display_valve = zrdr_findstring(entry, "DISPLAY_VALVE");
		PNT2D location;
		zrdr_findPNT2D(entry, "LOCATION", &location);
		char* animation = zrdr_findstring(entry, "ON_CALL_ANIMATION");
		char* music = zrdr_findstring(entry, "ON_CALL_MUSIC");
		bool sub_objective = zrdr_findtag(entry, "ISSUB_OBJECTIVE") != NULL;
		bool secondary = zrdr_findtag(entry, "ISSECONDARY") != NULL;
		bool compass = zrdr_findtag(entry, "NO_COMPASS_ICON") == NULL;

		if (name == NULL)
			continue;

		CMissionObjectiveCam* cam = new CMissionObjectiveCam;
		cam->Set(identifier, name, description, description2, description3, animation, music, valve, invalid_valve, display_valve, &location);
		cam->m_isSecondary = secondary;
		cam->m_isSubObjective = sub_objective;
		cam->m_isCompass = compass;
		cam->m_bExtraction = zrdr_findtag(entry, "ISEXTRACTION") != NULL;

		_zrdr* lines = zrdr_findtag(entry, "LINE_IDS");
		s32 count = lines != NULL && lines->IsArray() ? lines->array->integer - 1 : 0;

		for (s32 j = 0; j < count; j++)
			cam->m_vecLines.push_back(static_cast<u32>(lines->Get(j)->GetInt()));

		m_objectivecams.push_back(cam);
		SOCOM_PORT_TRACE("OBJ: %s '%s' at %.0f %.0f valve %s%s%s", identifier != NULL ? identifier : "-", name, location.x, location.y, valve != NULL ? valve : "-", secondary ? " secondary" : "", cam->m_bExtraction ? " extraction" : "");
	}
}

/* @socom-skeleton stub GetMissionCamByIdentifier__8CMissionFPCc */
CMissionCam * CMission::GetMissionCamByIdentifier(const char *identifier)
{
	/* 0x1f2bf0: the first mission camera of that identifier */
	for (std::list<CMissionCam*>::iterator it = m_missioncams.begin(); it != m_missioncams.end(); ++it)
	{
		CMissionCam* cam = *it;

		if (cam != NULL && strcmp(cam->m_identifier, identifier) == 0)
			return cam;
	}

	return NULL;
}

/* @socom-skeleton body TickInFirefight__8CMissionFf */
void CMission::TickInFirefight(f32 dT)
{
	// The "awareness counter" keeps track of how many entities -
	// saw the player. Enemies update the aware counter from -
	// animation events and their state machine.

	// This also controls the jukebox, where it will play combat -
	// music if at least ONE enemy entity saw you.
	
	u32 aware_counter = 0;
	
	if (ftsPlayer)
	{
		aware_counter = ftsPlayer->m_aware_counter;
	}

	// Is the player seen by anyone else?
	if (aware_counter < 1)
	{
		// Decrease the fight timer
		if (m_fighttimer > 0.0f)
		{
			m_fighttimer =- dT;
		}

		// We are no longer fighting enemies.
		// Go back to using stealth music.
		if (m_fighttimer <= 0.0f)
		{
			m_fighttimer = 0.0f;
			CSndJukebox::IsInFight(false);
		}
	}
	else
	{
		// Player is currently in a fight
		// Let the jukebox know!
		if (m_fighttimer <= 0.0f)
		{
			CSndJukebox::IsInFight(true);
		}

		m_fighttimer = 4.0f;
	}
}

